#include "blockfall_core.h"

#include <string.h>

namespace blockfall {
namespace {

// Each piece at rotation 0, inside a box of `box` x `box` squares. Rotations
// are generated by turning the box clockwise, so only these need checking.
struct Shape {
  uint8_t box;
  Cell cells[4];
};

const Shape kShapes[kPieceTypes] = {
    /* I */ {4, {{0, 1}, {1, 1}, {2, 1}, {3, 1}}},
    /* O */ {2, {{0, 0}, {1, 0}, {0, 1}, {1, 1}}},
    /* T */ {3, {{1, 0}, {0, 1}, {1, 1}, {2, 1}}},
    /* S */ {3, {{1, 0}, {2, 0}, {0, 1}, {1, 1}}},
    /* Z */ {3, {{0, 0}, {1, 0}, {1, 1}, {2, 1}}},
    /* J */ {3, {{0, 0}, {0, 1}, {1, 1}, {2, 1}}},
    /* L */ {3, {{2, 0}, {0, 1}, {1, 1}, {2, 1}}},
};

// Sideways shifts tried, in order, when a rotation doesn't fit in place.
const int8_t kKicks[] = {0, -1, 1, -2, 2};

// Points for clearing 0-4 rows at once, multiplied by the level.
const uint32_t kLinePoints[5] = {0, 100, 300, 500, 800};

constexpr uint32_t kFirstFallMs = 800;
constexpr uint32_t kFallStepMs = 70;
constexpr uint32_t kFastestFallMs = 100;

const Shape& shapeOf(PieceType type) { return kShapes[static_cast<uint8_t>(type)]; }

}  // namespace

void pieceCells(PieceType type, uint8_t rotation, Cell out[4]) {
  const Shape& s = shapeOf(type);
  for (int i = 0; i < 4; ++i) {
    int8_t x = s.cells[i].x;
    int8_t y = s.cells[i].y;
    for (uint8_t r = 0; r < (rotation & 3); ++r) {
      // Quarter turn clockwise inside the box: (x, y) -> (box-1-y, x).
      const int8_t turned_x = static_cast<int8_t>(s.box - 1 - y);
      y = x;
      x = turned_x;
    }
    out[i] = {x, y};
  }
}

// ---- Bag ---------------------------------------------------------------------

Bag::Bag(uint32_t seed) : rng_(seed) { refill(); }

void Bag::refill() {
  for (int i = 0; i < kPieceTypes; ++i) {
    items_[i] = static_cast<PieceType>(i);
  }
  // Fisher-Yates shuffle.
  for (int i = kPieceTypes - 1; i > 0; --i) {
    const int j = static_cast<int>(rng_.next() % static_cast<uint32_t>(i + 1));
    const PieceType tmp = items_[i];
    items_[i] = items_[j];
    items_[j] = tmp;
  }
  index_ = 0;
}

PieceType Bag::next() {
  const PieceType p = items_[index_++];
  if (index_ == kPieceTypes) {
    refill();
  }
  return p;
}

PieceType Bag::peek() const { return items_[index_]; }

// ---- Game --------------------------------------------------------------------

Game::Game(uint32_t seed) : bag_(seed), piece_{PieceType::kI, 0, 0, 0} { reset(seed); }

void Game::reset(uint32_t seed) {
  memset(board_, 0, sizeof(board_));
  bag_ = Bag(seed);
  state_ = State::kPlaying;
  score_ = 0;
  lines_ = 0;
  last_cleared_ = 0;
  spawn();
  ++revision_;
}

bool Game::fits(PieceType type, uint8_t rotation, int x, int y) const {
  Cell cells[4];
  pieceCells(type, rotation, cells);
  for (const Cell& c : cells) {
    const int bx = x + c.x;
    const int by = y + c.y;
    if (bx < 0 || bx >= kCols || by < 0 || by >= kRows || board_[by][bx] != 0) {
      return false;
    }
  }
  return true;
}

bool Game::moveLeft() {
  if (state_ != State::kPlaying || !fits(piece_.type, piece_.rotation, piece_.x - 1, piece_.y)) {
    return false;
  }
  --piece_.x;
  ++revision_;
  return true;
}

bool Game::moveRight() {
  if (state_ != State::kPlaying || !fits(piece_.type, piece_.rotation, piece_.x + 1, piece_.y)) {
    return false;
  }
  ++piece_.x;
  ++revision_;
  return true;
}

bool Game::rotate() {
  if (state_ != State::kPlaying) {
    return false;
  }
  const uint8_t next = static_cast<uint8_t>((piece_.rotation + 1) & 3);
  for (const int8_t dx : kKicks) {
    if (fits(piece_.type, next, piece_.x + dx, piece_.y)) {
      piece_.rotation = next;
      piece_.x = static_cast<int8_t>(piece_.x + dx);
      ++revision_;
      return true;
    }
  }
  return false;
}

bool Game::tick(bool soft_drop) {
  if (state_ != State::kPlaying) {
    return false;
  }
  if (fits(piece_.type, piece_.rotation, piece_.x, piece_.y + 1)) {
    ++piece_.y;
    if (soft_drop) {
      ++score_;
    }
    ++revision_;
    return false;
  }
  lock();
  return true;
}

void Game::hardDrop() {
  if (state_ != State::kPlaying) {
    return;
  }
  uint32_t rows = 0;
  while (fits(piece_.type, piece_.rotation, piece_.x, piece_.y + 1)) {
    ++piece_.y;
    ++rows;
  }
  score_ += 2 * rows;
  lock();
}

uint32_t Game::fallIntervalMs() const {
  const uint32_t speedup = (level() - 1) * kFallStepMs;
  return speedup >= kFirstFallMs - kFastestFallMs ? kFastestFallMs : kFirstFallMs - speedup;
}

uint8_t Game::cell(int x, int y) const {
  if (x < 0 || x >= kCols || y < 0 || y >= kRows) {
    return 0;
  }
  return board_[y][x];
}

void Game::setCellForTest(int x, int y, uint8_t value) {
  if (x >= 0 && x < kCols && y >= 0 && y < kRows) {
    board_[y][x] = value;
  }
}

void Game::setPieceForTest(PieceType type, uint8_t rotation, int x, int y) {
  piece_ = {type, static_cast<uint8_t>(rotation & 3), static_cast<int8_t>(x), static_cast<int8_t>(y)};
  ++revision_;
}

void Game::lock() {
  Cell cells[4];
  pieceCells(piece_.type, piece_.rotation, cells);
  const uint8_t value = static_cast<uint8_t>(static_cast<uint8_t>(piece_.type) + 1);
  for (const Cell& c : cells) {
    board_[piece_.y + c.y][piece_.x + c.x] = value;
  }
  const uint32_t level_before = level();
  last_cleared_ = clearLines();
  score_ += kLinePoints[last_cleared_] * level_before;
  lines_ += last_cleared_;
  spawn();
  ++revision_;
}

void Game::spawn() {
  const PieceType type = bag_.next();
  const int8_t x = static_cast<int8_t>((kCols - shapeOf(type).box) / 2);
  piece_ = {type, 0, x, 0};
  if (!fits(type, 0, x, 0)) {
    state_ = State::kGameOver;
  }
}

uint8_t Game::clearLines() {
  uint8_t cleared = 0;
  int write = kRows - 1;
  // Copy rows bottom-up, skipping full ones, then blank what's left on top.
  for (int read = kRows - 1; read >= 0; --read) {
    bool full = true;
    for (int x = 0; x < kCols && full; ++x) {
      full = board_[read][x] != 0;
    }
    if (full) {
      ++cleared;
      continue;
    }
    if (write != read) {
      memcpy(board_[write], board_[read], kCols);
    }
    --write;
  }
  for (; write >= 0; --write) {
    memset(board_[write], 0, kCols);
  }
  return cleared;
}

}  // namespace blockfall
